class Solution {
  public long[] findMaxSum(int[] nums1, int[] nums2, int k) {
    int n = nums1.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(nums1[a], nums1[b]));
    java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
    long sum = 0;
    long[] ans = new long[n];
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && nums1[order[j]] == nums1[order[i]]) {
        ans[order[j]] = sum;
        j++;
      }
      for (int t = i; t < j; t++) {
        int v = nums2[order[t]];
        heap.add(v);
        sum += v;
        if (heap.size() > k) sum -= heap.poll();
      }
      i = j;
    }
    return ans;
  }
}
